import base64
import json
import re

txt = (data.get('raw') or '').strip()
if not isinstance(txt, str):
    txt = json.dumps(txt, ensure_ascii=False)

out = {'ok': False, 'error': '', 'access_token': '', 'sso_uid': ''}


def _find_obj(s):
    # 从任意文本里抠第一个含 access_token/error 的平衡 JSON：模型常把结果包在
    # <summary>/散文/代码块里（run 53 就这么丢过一张真票）。
    try:
        o = json.loads(s)
        if isinstance(o, dict):
            return o
    except Exception:
        pass
    depth = 0
    start = -1
    for i, ch in enumerate(s):
        if ch == '{':
            if depth == 0:
                start = i
            depth += 1
        elif ch == '}':
            depth -= 1
            if depth == 0 and start >= 0:
                try:
                    o = json.loads(s[start:i + 1])
                except Exception:
                    continue
                if isinstance(o, dict) and (o.get('access_token') or o.get('error')):
                    return o
    return {}


obj = _find_obj(txt)
if isinstance(obj, dict) and obj.get('error'):
    out['error'] = '登录失败: ' + str(obj['error'])[:180]
elif not (isinstance(obj, dict) and str(obj.get('access_token') or '').strip()):
    out['error'] = '登录输出里没有 access_token（模型未产出预期 JSON）: ' + txt[:160]
else:
    token = str(obj['access_token']).strip()
    out['access_token'] = token
    if obj.get('refresh_token'):
        out['refresh_token'] = str(obj['refresh_token']).strip()
    if obj.get('token_expires_at'):
        out['token_expires_at'] = str(obj['token_expires_at']).strip()
    uid = ''
    for k in ('sso_uid', 'uid', 'user_id', 'ssoUid'):
        v = str(obj.get(k) or '').strip()
        if v:
            uid = v
            break
    if not uid:
        try:
            seg = token.split('.')[1]
            seg += '=' * (-len(seg) % 4)
            uid = str(json.loads(base64.urlsafe_b64decode(seg)).get('jti') or '').strip()
        except Exception:
            uid = ''
    if not uid:
        out['error'] = '无法确定 sso_uid（登录输出无 uid、JWT 无 jti），Redis 键无从落'
    else:
        out['sso_uid'] = uid
        out['ok'] = True
# ⚠️ 绝不 raise：raise 让子进程非零退出，引擎会返回 stdout/stderr 字典，
# 再过 output_schema 报「缺 access_token」——把真因（登录失败）完全掩盖了。
# 失败写成 ok=false 的合规输出，靠边的 when 跳过 store、不写脏票。
result = out
